#!/usr/bin/env bash
# usage: bash art/portraits/gen_new.sh <out.png> "<character + expression description>"   (run from repo root)
# Designs a NEW character bust in the house style, using Moxie's neutral anchor as a style/framing reference.
STY='House style: expressive cel-shaded anime (Mob Psycho 100 / Idaten Deities energy), bold clean black ink outline of confident varying weight, flat colours with exactly one hard-edged shadow tone, no gradients, no soft airbrush, no painterly rendering, no photorealism. The attached image is a STYLE AND FRAMING reference only (a different character from the same game): match its line weight, flat cel shading, level of detail, head size in the frame and bust crop exactly, but do NOT copy that character, her face, hair, headphones or clothes. Bust portrait for a game dialogue box: head and shoulders down to mid-chest, three-quarter view FACING SCREEN-LEFT (the mirror of the reference direction), head centred, generous empty headroom above, the bust running off the bottom edge, nothing cropped at the sides or top. Fully transparent background, no backdrop, no ground, no drop shadow, no text, no border, no watermark, no other characters.'
IMG_BG=transparent bash "${IMG_TOOL:-tools/img}" edit "$1" "$2 $STY" art/portraits/raw/moxie_neutral_b.png
